const AUDIT = join(ROOT, 'qa', 'servicing-seed', 'trigger-audit.md')
const DOOR = join(ROOT, 'qa', 'servicing-seed', 'door-dry-run.sql')

const A = '3f2b2df7-40b1-4921-80e2-09981c819642' // the test agent
const F = '00000000-0000-4000-8000-00000000f001' // the test fulfillment account: the placeholder, so the door file runs as written
const R = 'aaaaaaaa-aaaa-4aaa-8194-00000000000b' // a real-looking agent with a policy this month
const O = 'aaaaaaaa-aaaa-4aaa-8194-00000000000c' // another agent with is_sample rows
const REP = 'aaaaaaaa-aaaa-4aaa-8194-00000000000d' // a real rep
const Z = 'aaaaaaaa-aaaa-4aaa-8194-00000000000e' // an admin, with email on
const UNFLAGGED = 'dddddddd-dddd-4ddd-8194-000000000001'
const O_POLICY = 'dddddddd-dddd-4ddd-8194-000000000002'
const O_LEAD = 'dddddddd-dddd-4ddd-8194-000000000003'
const SEEDED = ['policies', 'policy_fulfillment_details', 'policy_events', 'policy_messages', 'leads',
  'lead_sms_replies', 'lead_followup_sms_log', 'inbound_events', 'servicing_tasks', 'help_calls']
const STAGES = { setting_up: 2, protected: 7, needs_attention: 2, ongoing: 1, ended: 1 }
const DISABLED = ['policies_recompute_leaderboard', 'policies_check_goal_milestones', 'policy_messages_notify_trigger']
// May change when the seed and wipe run: what they write, and the permanent delete log (153).
const MAY_CHANGE = new Set([...SEEDED, 'admin_audit_log'])
// Money tables named on their own lines; every other table is covered by c5 too.
const MONEY = ['fulfillment_pay', 'fulfillment_cancels', 'fulfillment_cancel_checks', 'fulfillment_cancel_events',
  'fulfillment_pay_runs', 'fulfillment_payouts', 'fulfillment_payout_accounts', 'fulfillment_time_entries',
  'fulfillment_recordings', 'fulfillment_missed_calls', 'agent_lead_ledger', 'agent_inbound_spend', 'agent_inbound_spend_log']

let failed = 0
const ran = new Set()
const check = (id, label, ok, why = '') => {
  ran.add(id)
  if (!ok) failed++
  console.log(`${ok ? 'PASS' : 'FAIL'} [${id}] ${label}${!ok && why ? `: ${why}` : ''}`)
}
const section = t => console.log(`\n== ${t} ==`)

// ── Python: the real generators ─────────────────────────────────────────────
function python(args) {
  for (const py of ['python', 'python3', 'py']) {
    const r = spawnSync(py, args, { cwd: ROOT, encoding: 'utf8', maxBuffer: 1 << 26, env: { ...process.env, PYTHONDONTWRITEBYTECODE: '1' } })
    if (r.error?.code === 'ENOENT') continue
    if (r.status !== 0) throw new Error(`${py} ${args.join(' ')} exited ${r.status}: ${r.stderr}`)
    return r.stdout
  }
  throw new Error('Python is not available: the seed SQL cannot be generated, so nothing was tested')
}
const genSeed = (fid = F) => python(['scripts/seed_agent_sample.py', '--fulfillment-id', fid])
const genWipe = () => python(['scripts/wipe_agent_sample.py'])

// ── database helpers ────────────────────────────────────────────────────────
const rows = async (db, sql, params) => (await db.query(sql, params)).rows
const one = async (db, sql, params) => (await rows(db, sql, params))[0]
const count = async (db, sql, params) => Number(Object.values(await one(db, sql, params))[0])

async function fresh(base) {
  const db = await base.clone()
  await db.exec('set search_path = "$user", public, extensions')
  return db
}

// Runs generated SQL as the SQL editor would. On a failure the transaction is rolled back and the error returned.
async function run(db, sql) {
  try {
    await db.exec(sql)
    return null
  } catch (e) {
    if (db.isInTransaction()) await db.exec('rollback')
    return e
  }
}
async function mustRun(db, sql, what) {
  const e = await run(db, sql)
  if (e) throw new Error(`${what} failed: ${e.code ?? ''} ${e.message}`)
}

