// O's, R's and the rep's rows and the unflagged row, as text: must never change.
async function othersSnapshot(db) {
  const people = `('${O}', '${R}', '${REP}')`
  const policyScope = `(select id from public.policies where agent_id in ${people} or id = '${UNFLAGGED}')`
  const leadScope = `(select id from public.leads where assigned_rep_id in ${people})`
  const where = {
    profiles: `id in ${people}`,
    policies: `id in ${policyScope}`,
    policy_fulfillment_details: `policy_id in ${policyScope}`,
    policy_events: `policy_id in ${policyScope}`,
    policy_messages: `policy_id in ${policyScope}`,
    leads: `id in ${leadScope}`,
    lead_sms_replies: `lead_id in ${leadScope}`,
    lead_followup_sms_log: `lead_id in ${leadScope}`,
    inbound_events: `lead_id in ${leadScope}`,
    servicing_tasks: `agent_id in ${people}`,
    help_calls: `transfer_agent_id in ${people}`,
    notifications: `profile_id in ${people}`,
  }
  const out = {}
  for (const [t, w] of Object.entries(where)) {
    out[t] = (await rows(db, `select to_jsonb(x)::text as j from public.${t} x where ${w} order by 1`)).map(r => r.j)
  }
  return JSON.stringify(out)
}

// md5 of every table outside the ones allowed to change.
async function otherTablesHash(db) {
  const ts = await rows(db, `select n.nspname as s, c.relname as t from pg_class c join pg_namespace n on n.oid = c.relnamespace
                              where c.relkind = 'r' and n.nspname in ('public', 'net', 'cron', 'vault', 'auth') order by 1, 2`)
  const out = {}
  for (const { s, t } of ts) {
    if (s === 'public' && MAY_CHANGE.has(t)) continue
    out[`${s}.${t}`] = (await one(db, `select md5(coalesce(string_agg(x::text, '|' order by x::text), '')) as h from ${s}.${t} x`)).h
  }
  return out
}
const hashDiff = (a, b) => Object.keys({ ...a, ...b }).filter(k => a[k] !== b[k])

// agent_clients for the test agent, flagged rows only.
const flaggedClients = db => rows(db, `select * from public.agent_clients where agent_id = '${A}' and is_sample`)
const sampleCounts = async db => {
  const out = {}
  for (const t of SEEDED) out[t] = await count(db, `select count(*) from public.${t} where is_sample`)
  return out
}

// What the test agent's weekly meter reads. It only answers the agent or an admin, so ask as the agent.
async function weeklyUsed(db) {
  await db.exec(`begin; select set_config('request.jwt.claims', '{"sub":"${A}","role":"authenticated"}', true);`)
  const r = await one(db, `select used from public.agent_weekly_usage('${A}')`)
  await db.exec('rollback')
  return Number(r.used)
}

// Every sweep the brief names, at every moment that could matter, then each plain-SQL cron as written.
async function runSweeps(db) {
  const times = ["now()", "now() + interval '4 minutes'", "now() + interval '20 minutes'", "now() + interval '1 day'", "now() + interval '8 days'"]
  await db.query('select public.notify_call_times()')
  await db.query('select public.notify_hourly()')
  await db.query('select public.missed_sweep()')
  await db.query('select public.recovery_sweep()')
  for (const t of times) {
    await db.query(`select public.notify_call_times(${t})`)
    await db.query(`select public.notify_hourly(${t})`)
    await db.query(`select public.missed_sweep(${t})`)
  }
  const jobs = await rows(db, `select jobname, command from cron.job where command not like '%fulfillment_cron_post%' order by 1`)
  for (const j of jobs) await db.exec(j.command)
  // The two posting jobs that are gated on their queue: must stay gated.
  for (const name of ['notify-email', 'notify-push']) {
    const j = await one(db, 'select command from cron.job where jobname = $1', [name])
    await db.exec(j.command)
  }
  return jobs.map(j => j.jobname)
}

// ── the audit ───────────────────────────────────────────────────────────────
function readAudit() {
  const entries = []
  for (const line of readFileSync(AUDIT, 'utf8').split('\n')) {
    const m = /^\| `([\w-]+)` \| `([\w-]+)` \|(.*)\|\s*$/.exec(line)
    if (m) entries.push({ on: m[1], name: m[2], cells: m[3].split('|').map(s => s.trim()) })
  }
  return entries
}

async function main() {
  const t0 = Date.now()
  const seedSql = genSeed()
  const wipeSql = genWipe()

  const { db: base, files, failures } = await replayedDb()
  console.log(`test-seed-sample: ${files.length} migrations replayed in PGlite, ${failures.length} failed. In memory; no network.`)
  for (const f of failures) console.log(`  replay failure ${f.file}: ${f.sqlstate} ${f.message}`)
  if (failures.length) throw new Error('a migration failed in the replay, so the seed would be tested against the wrong schema')
  await base.exec('set search_path = "$user", public, extensions')
  await mustRun(base, FIXTURES, 'the fixtures')

  section('fixtures')
  check('fx1', "R has a policy this month and leaderboard_rank1_notified_month is null",
    await count(base, `select count(*) from public.policies where agent_id = '${R}'`) === 1
    && (await one(base, `select leaderboard_rank1_notified_month m from public.profiles where id = '${R}'`)).m === null)
  check('fx2', "O holds an is_sample row in every seeded table",
    (await Promise.all(SEEDED.map(t => count(base, `select count(*) from public.${t} where is_sample`)))).every(n => n >= 1))

  const before = {
    others: await othersSnapshot(base),
    hash: await otherTablesHash(base),
    samples: await sampleCounts(base),
    used: await weeklyUsed(base),
    queue: await count(base, 'select count(*) from net.http_request_queue'),
    ids: Object.fromEntries(await Promise.all(SEEDED.filter(t => t !== 'policy_fulfillment_details').map(async t => [t, new Set((await rows(base, `select id::text as id from public.${t}`)).map(r => r.id))]))),
    audit: await count(base, 'select count(*) from public.admin_audit_log'),
  }

  // ── a. the 13 clients ─────────────────────────────────────────────────────
  section('a. seed: agent_clients for the test agent, flagged rows only')
  const db = await fresh(base)
  await mustRun(db, seedSql, 'the seed')
  const clients = await flaggedClients(db)
  check('a1', `13 clients (got ${clients.length})`, clients.length === 13)
  const stageCount = s => clients.filter(c => c.stage === s).length
  const stageText = Object.keys(STAGES).map(s => `${s}=${stageCount(s)}`).join(', ')
  check('a2', `stages ${stageText}`, Object.entries(STAGES).every(([s, n]) => stageCount(s) === n))
  const twoPolicies = clients.filter(c => c.policy_count === 2).length
  check('a3', `at least 2 clients with 2 policies (got ${twoPolicies})`, twoPolicies >= 2)
  const withRequests = clients.filter(c => c.open_requests > 0)
  check('a4', `2 with open requests (got ${withRequests.length}), both protected with 1 each`,
    withRequests.length === 2 && withRequests.every(c => c.stage === 'protected' && c.open_requests === 1))
  const linked = await count(db, `select count(*) from public.leads l join public.policies p on p.id = l.client_policy_id
                                   where l.is_sample and p.is_sample and p.agent_id = '${A}' and l.assigned_rep_id = '${A}'
                                     and l.phone = p.client_phone and l.contact_name = p.client_first_name || ' ' || p.client_last_name`)
  check('a5', `at least 3 clients from leads, client_policy_id linked (got ${linked})`, linked >= 3)
  const noLead = await count(db, `select count(*) from public.agent_clients c where c.agent_id = '${A}' and c.is_sample
                                   and not exists (select 1 from public.leads l where l.client_policy_id = any (c.policy_ids))`)
  check('a6', `at least 3 existing clients with no lead (got ${noLead})`, noLead >= 3)
  const replaced = await rows(db, `select distinct p.replaced_old_policy r from public.agent_clients c join public.policies p on p.id = any (c.policy_ids)
                                    where c.agent_id = '${A}' and c.is_sample and c.stage = 'setting_up'`)
  check('a7', 'setting-up clients cover replaced_old_policy true and false', replaced.length === 2 && replaced.some(r => r.r === true) && replaced.some(r => r.r === false))
  const cancelledDone = await count(db, `select count(*) from public.agent_clients c join public.policies p on p.id = any (c.policy_ids)
                                          join public.policy_events e on e.policy_id = p.id and e.kind = 'cancelled' and e.is_sample
                                         where c.agent_id = '${A}' and c.is_sample and c.stage = 'protected'
                                           and p.replaced_old_policy and p.fulfillment_stage = 'Complete'
                                           and p.cancellation_confirmation is not null and p.fulfillment_completed_at < now()`)
  check('a8', `a protected client has its old policy cancelled as a done step (got ${cancelledDone})`, cancelledDone >= 1)
  const lapse = await rows(db, `select c.stage, t.status, t.outcome, t.done_at >= now() - interval '14 days' as recent, t.requested_by from public.agent_clients c
                                  join public.servicing_tasks t on t.policy_id = any (c.policy_ids) and t.kind = 'lapse_save'
                                 where c.agent_id = '${A}' and c.is_sample order by c.stage, t.status`)
  check('a9', 'one open lapse_save, one saved in the last 14 days, one ended with an outcome',
    lapse.length === 3 && lapse.filter(l => l.stage === 'needs_attention' && !l.outcome && l.status !== 'done').length === 1
    && lapse.filter(l => l.stage === 'needs_attention' && l.outcome === 'saved' && l.recent).length === 1
    && lapse.filter(l => l.stage === 'ended' && l.outcome === 'lapsed').length === 1)
  const noBy = await count(db, `select count(*) from public.servicing_tasks where is_sample and agent_id = '${A}' and requested_by not in ('agent', 'client', 'system')`)
  const agentAsked = await count(db, `select count(*) from public.servicing_tasks where is_sample and agent_id = '${A}' and requested_by = 'agent' and requested_by_id = '${A}'`)
  const eventsMatch = await count(db, `select count(*) from public.servicing_tasks t where t.is_sample and t.agent_id = '${A}' and t.requested_by <> 'system'
                                        and not exists (select 1 from public.policy_events e where e.policy_id = t.policy_id and e.kind = 'service_request'
                                                         and e.detail ->> 'request_id' = t.id::text and e.is_sample)`)
  const msgs = await count(db, `select count(distinct policy_id) from public.policy_messages where is_sample and policy_id in (select id from public.policies where agent_id = '${A}')`)
  check('a10', 'tasks have requested_by, requests have matching policy_events, messages on the clients', noBy === 0 && agentAsked >= 1 && eventsMatch === 0 && msgs >= 8, `noBy ${noBy}, agent ${agentAsked}, unmatched ${eventsMatch}, threads ${msgs}`)
  const noDate = clients.filter(c => c.stage !== 'ended' && !c.next_date).map(c => c.client_last_name)
  check('a11', 'every client that is not ended has a next date, with no scheduled_call_at', noDate.length === 0, noDate.join(', '))

  // ── b. every seeded row ───────────────────────────────────────────────────
  section('b. every seeded row is_sample and under the test agent')
  const owner = {
    policies: `x.agent_id = '${A}'`,
    policy_events: `x.agent_id = '${A}' and x.policy_id in (select id from public.policies where agent_id = '${A}')`,
    policy_messages: `x.policy_id in (select id from public.policies where agent_id = '${A}') and x.sender_id in ('${A}', '${F}')`,
    leads: `x.assigned_rep_id = '${A}'`,
    lead_sms_replies: `x.lead_id in (select id from public.leads where assigned_rep_id = '${A}')`,
    lead_followup_sms_log: `x.lead_id in (select id from public.leads where assigned_rep_id = '${A}')`,
    inbound_events: `x.agent_id = '${A}' and x.lead_id in (select id from public.leads where assigned_rep_id = '${A}')`,
    servicing_tasks: `x.agent_id = '${A}'`,
    help_calls: `x.transfer_agent_id = '${A}'`,
  }
  for (const [t, ok] of Object.entries(owner)) {
    const known = [...before.ids[t]]
    const added = await rows(db, `select x.is_sample, (${ok}) as own from public.${t} x where not (x.id::text = any ($1))`, [known])
    check(`b-${t}`, `${t}: ${added.length} new row(s), all is_sample and under the test agent`,
      added.length > 0 && added.every(r => r.is_sample === true && r.own === true))
  }
  const details = await rows(db, `select d.is_sample, p.agent_id::text as agent from public.policy_fulfillment_details d join public.policies p on p.id = d.policy_id
                                   where d.policy_id not in ('${O_POLICY}', '${UNFLAGGED}')
                                     and p.agent_id = '${A}'`)
  check('b-details', `policy_fulfillment_details: ${details.length} new row(s), all is_sample and under the test agent`,
    details.length > 0 && details.every(r => r.is_sample === true))
  const sampleP = await rows(db, `select to_jsonb(p) as j from public.policies p where is_sample and agent_id = '${A}'`)
  const phones = [...sampleP.map(r => r.j.client_phone), ...(await rows(db, `select phone from public.leads where is_sample and assigned_rep_id = '${A}'`)).map(r => r.phone)]
  check('b-phones', 'every client and lead phone is +1555010xxxx', phones.length > 0 && phones.every(p => /^\+1555010\d{4}$/.test(p)))
  check('b-consent', 'sms_consent false on every sample policy', sampleP.every(r => r.j.sms_consent === false))
  const textPhones = [...seedSql.matchAll(/'(\+?\d[\d -]{6,})'/g)].map(m => m[1]).filter(p => !/^\d{8}-/.test(p))
  check('b-sqltext', `the generated SQL holds no phone outside the range (${textPhones.length} checked) and no literal date`,
    textPhones.length > 0 && textPhones.every(p => /^\+1555010\d{4}$/.test(p)) && !/\b\d{4}-\d{2}-\d{2}\b/.test(seedSql))
  check('b-p729', 'the seed did not mark or change the unflagged P729-shaped row', (await one(db, `select is_sample from public.policies where id = '${UNFLAGGED}'`)).is_sample === false)

  // ── rules on the data ─────────────────────────────────────────────────────
  section('data rules: dates and sweeps')
  check('r1', "the SQL takes dates from date_trunc('week', now())", seedSql.includes("date_trunc('week', now())"))
  const late = await count(db, `select count(*) from public.policies where is_sample and agent_id = '${A}'
                                 and created_at >= date_trunc('week', now()) - interval '2 days'`)
  check('r2', "every policy's created_at is date_trunc('week', now()) minus at least 2 days", late === 0, `${late} too new`)
  const inSummary = await count(db, `select count(*) from public.policies where is_sample and agent_id = '${A}'
                                      and (created_at >= date_trunc('week', now()) - interval '8 days'
                                           or fulfillment_completed_at >= date_trunc('week', now()) - interval '8 days')`)
  check('r3', 'and old enough to stay out of the Monday summary of a seed run on Monday morning', inSummary === 0, `${inSummary} too new`)
  const recoveryKeys = sampleP.flatMap(r => Object.entries(r.j).filter(([k, v]) => /^(recovery|missed)_/.test(k) && k !== 'recovery_token' && v !== null).map(([k]) => k))
  check('r4', 'no recovery_* or missed_* value on any sample policy', recoveryKeys.length === 0, recoveryKeys.join(', '))
  check('r5', 'no scheduled_call_at, next_lapse_check_at or no_answer on any sample policy',
    sampleP.every(r => r.j.scheduled_call_at === null && r.j.next_lapse_check_at === null && r.j.last_call_outcome !== 'no_answer'))
  const repRows = sampleP.map(r => r.j)
  const noOld = repRows.filter(p => p.replaced_old_policy === false)
  check('r6', `all ${repRows.length - noOld.length} rows with an old policy hold the test fulfillment account, so autoassign has nothing to pick`,
    repRows.filter(p => p.replaced_old_policy !== false).every(p => p.assigned_fulfillment_id === F))
  check('r7', `the ${noOld.length} rows with no old policy hold no rep (187 refuses one and autoassign skips them)`, noOld.length > 0 && noOld.every(p => p.assigned_fulfillment_id === null))
  const repsHit = await count(db, `select count(*) from public.policies where assigned_fulfillment_id = '${REP}' and is_sample and agent_id = '${A}'`)
  check('r8', 'no sample policy reached the real rep', repsHit === 0)

  // ── d. nobody else hears about it ─────────────────────────────────────────
  section('d. after the seed and after every sweep')
  // O's one bell is a fixture, there so the wipe has another agent's bell to leave alone.
  const outside = async (d, table, col) => count(d, `select count(*) from public.${table} x where ${col} not in ('${A}', '${F}')${table === 'notifications' ? " and x.title is distinct from 'Other agent bell'" : ''}`)
  const queue = () => count(db, 'select count(*) from net.http_request_queue')
  const money = async d => Object.fromEntries(await Promise.all(MONEY.map(async t => [t, await count(d, `select count(*) from public.${t}`)])))
  const billingTables = (await rows(base, `select c.relname t from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r'
                                            and (c.relname ~ 'billing|stripe|subscription|ledger|topup|payment|commission|charge')`)).map(r => r.t)
  const billing = async d => Object.fromEntries(await Promise.all(billingTables.map(async t => [t, await count(d, `select count(*) from public.${t}`)])))
  const moneyBefore = await money(base)
  const billingBefore = await billing(base)

  const afterSeed = async (label, id) => {
    const n = await outside(db, 'notifications', 'profile_id')
    const e = await outside(db, 'notification_emails', 'profile_id')
    const p = await outside(db, 'notification_pushes', 'profile_id')
    check(`${id}1`, `${label}: 0 notifications, 0 emails and 0 pushes for anyone but the test accounts`, n === 0 && e === 0 && p === 0, `${n} notifications, ${e} emails, ${p} pushes`)
    const q = await queue()
    check(`${id}2`, `${label}: net.http_request_queue unchanged (${before.queue})`, q === before.queue, `${q}`)
    const m = await money(db)
    const changed = MONEY.filter(t => m[t] !== moneyBefore[t])
    check(`${id}3`, `${label}: 0 new rows in fulfillment_pay, fulfillment_cancels, fulfillment_payouts, the prepaid ledger and the other payout tables`, changed.length === 0, changed.join(', '))
    const b = await billing(db)
    const bChanged = billingTables.filter(t => b[t] !== billingBefore[t])
    check(`${id}4`, `${label}: 0 new rows in the ${billingTables.length} billing tables (${billingTables.join(', ')})`, billingTables.length > 0 && bChanged.length === 0, bChanged.join(', '))
    const month = (await one(db, `select leaderboard_rank1_notified_month m, goal_50_notified_month g from public.profiles where id = '${R}'`))
    check(`${id}5`, `${label}: R's rank-1 and goal months still null`, month.m === null && month.g === null, JSON.stringify(month))
  }
  await afterSeed('after the seed', 'd')
  const usedAfter = await weeklyUsed(db)
  const cronRan = await runSweeps(db)
  console.log(`  ran notify_call_times, notify_hourly, missed_sweep at 5 moments, recovery_sweep, and every plain-SQL cron: ${cronRan.join(', ')}`)
  await afterSeed('after the sweeps', 'e')
  const samplesAfterSweep = await rows(db, `select id, scheduled_call_at, assigned_fulfillment_id, missed_step, recovery_step from public.policies where is_sample and agent_id = '${A}'`)
  check('d6', 'the sweeps moved no sample policy', samplesAfterSweep.every(p => p.scheduled_call_at === null && p.missed_step === null && p.recovery_step === null))
  check('d7', 'the sweeps put no strike on anyone', await count(db, 'select count(*) from public.fulfillment_missed_calls') === 0)
  const testBells = await count(db, `select count(*) from public.notifications where profile_id in ('${A}', '${F}')`)
  check('d8', `the test accounts got no bell either (${testBells})`, testBells === 0)
  await db.exec(`update public.recovery_config set sms_live = true`)
  const claimed = (await rows(db, 'select * from public.recovery_claim_due(100)')).length + (await rows(db, 'select * from public.missed_claim_due(100)')).length
  check('d9', 'recovery-sms would claim 0 sample rows even with sms_live on (this clone only)', claimed === 0, `${claimed}`)
  await db.close()

  // The Monday email reaches admins: same words with or without the samples.
  const mondayAt = "date_trunc('week', now() at time zone 'America/Chicago') + interval '8 hours'"
  const mondaySummary = async d => {
    await d.exec(`update public.profiles set role = 'admin', is_active = true where id = '${Z}'`)
    await d.query(`select public.notify_hourly((${mondayAt}) at time zone 'America/Chicago')`)
    return (await rows(d, `select subject, body from public.notification_emails where profile_id = '${Z}' and type = 'monday_summary'`))
  }
  const noSeed = await fresh(base)
  const seeded = await fresh(base)
  await mustRun(seeded, seedSql, 'the seed')
  const mA = await mondaySummary(noSeed)
  const mB = await mondaySummary(seeded)
  await noSeed.close(); await seeded.close()
  check('d10', `the admin's Monday summary reads the same with the samples ("${mB[0]?.subject}")`, mA.length === 1 && JSON.stringify(mA) === JSON.stringify(mB), `${JSON.stringify(mA)} vs ${JSON.stringify(mB)}`)

  // ── e. triggers ───────────────────────────────────────────────────────────
  section('e. triggers after commit')
  const dbE = await fresh(base)
  await mustRun(dbE, seedSql, 'the seed')
  const states = await rows(dbE, `select tgname::text n, tgenabled::text e from pg_trigger where tgname = any ($1)`, [DISABLED])
  check('e-enabled', `${DISABLED.join(', ')} read tgenabled = 'O' after commit`, states.length === DISABLED.length && states.every(s => s.e === 'O'), JSON.stringify(states))
  const anyOff = await rows(dbE, `select c.relname::text t, g.tgname::text n, g.tgenabled::text e from pg_trigger g join pg_class c on c.oid = g.tgrelid
                                   where not g.tgisinternal and c.relname = any ($1) and g.tgenabled <> 'O'`, [SEEDED])
  check('e-all', 'every trigger on every seeded table reads O after commit', anyOff.length === 0, JSON.stringify(anyOff))
  check('e-skip', 'skip_assign_notify does not outlive the transaction', (await one(dbE, `select coalesce(current_setting('ohvara.skip_assign_notify', true), '') v`)).v !== 'on')
  await dbE.close()
  const offAt = DISABLED.map(n => seedSql.indexOf(` disable trigger ${n};`))
  const onAt = DISABLED.map(n => seedSql.indexOf(` enable trigger ${n};`))
  check('e-order', 'the SQL disables them after the wipe and before the first insert, and enables them before commit',
    offAt.every(i => i > seedSql.indexOf('end $wipe$;') && i < seedSql.indexOf('insert into')) && onAt.every(i => i > seedSql.lastIndexOf('insert into') && i < seedSql.lastIndexOf('commit;')))
  const rollback = await fresh(base)
  const failing = seedSql.replace("-- The flagged clients must read", "select 1 / 0;\n-- The flagged clients must read")
  const err = await run(rollback, failing)
  const stillOn = await rows(rollback, `select tgenabled::text e from pg_trigger where tgname = any ($1)`, [DISABLED])
  check('e-rollback', 'a failure mid-seed rolls back: triggers on, no sample rows, unflagged row kept',
    !!err && stillOn.every(s => s.e === 'O')
    && await count(rollback, `select count(*) from public.policies where is_sample and agent_id = '${A}'`) === 0
    && await count(rollback, `select count(*) from public.policies where id = '${UNFLAGGED}'`) === 1)
  await rollback.close()

  // ── f. the weekly meter ───────────────────────────────────────────────────
  section('f. agent_weekly_usage')
  check('f1', `agent_weekly_usage(test agent).used unchanged by the seed (${before.used} to ${usedAfter})`, usedAfter === before.used, `${before.used} to ${usedAfter}`)
  for (const tz of ['Pacific/Honolulu', 'America/Chicago', 'Asia/Tokyo']) {
    const d = await fresh(base)
    await d.exec(`set time zone '${tz}'; update public.profiles set timezone = '${tz}' where id = '${A}';`)
    await mustRun(d, seedSql, 'the seed')
    const used = await weeklyUsed(d)
    check(`f-${tz}`, `used unchanged with the SQL and the agent on ${tz}`, used === before.used, `${used}`)
    await d.close()
  }
  const meter = await fresh(base)
  await meter.exec(`insert into public.policies (agent_id, client_first_name, client_last_name, status, fulfillment_assigned, fulfillment_stage, assigned_fulfillment_id)
                    values ('${A}', 'Meter', 'Control', 'Submitted', true, 'Pending', '${F}')`)
  check('f-control', 'control: a real booking made now does move the meter, so f1 could fail', await weeklyUsed(meter) === before.used + 1)
  await meter.close()

  // ── c. seed, wipe, seed ───────────────────────────────────────────────────
  section('c. seed, wipe, seed, running the generated SQL each time')
  const c = await fresh(base)
  await mustRun(c, genSeed(), 'seed 1')
  const first = await sampleCounts(c)
  check('c1', 'after seed 1: O, R and the unflagged row byte-identical', await othersSnapshot(c) === before.others)
  await mustRun(c, genWipe(), 'the wipe')
  const wiped = await sampleCounts(c)
  check('c2', 'after the wipe: flagged rows back to O\'s alone in every table', JSON.stringify(wiped) === JSON.stringify(before.samples), `${JSON.stringify(wiped)} vs ${JSON.stringify(before.samples)}`)
  check('c3', 'after the wipe: O, R and the unflagged row byte-identical', await othersSnapshot(c) === before.others)
  const tasksLeft = await count(c, `select count(*) from public.servicing_tasks where agent_id = '${A}'`)
  check('c4', 'after the wipe: servicing_tasks gone through the cascade (the SQL never deletes from it)', tasksLeft === 0 && !/delete\s+from\s+(public\.)?servicing_tasks/i.test(wipeSql), `${tasksLeft} left`)
  const diff1 = hashDiff(before.hash, await otherTablesHash(c))
  check('c5', 'after the wipe: every table outside the seeded ones and the delete log byte-identical', diff1.length === 0, diff1.join(', '))
  const logged = await count(c, `select count(*) from public.admin_audit_log`) - before.audit
  check('c6', `the delete log keeps one permanent row per wiped policy, by design (${logged})`, logged === first.policies - before.samples.policies)
  await mustRun(c, genSeed(), 'seed 2')
  const second = await sampleCounts(c)
  check('c7', `seed 2: same counts as seed 1 (${JSON.stringify(second)})`, JSON.stringify(first) === JSON.stringify(second), `${JSON.stringify(first)} vs ${JSON.stringify(second)}`)
  check('c8', 'seed 2: O, R and the unflagged row byte-identical', await othersSnapshot(c) === before.others)
  const diff2 = hashDiff(before.hash, await otherTablesHash(c))
  check('c9', 'seed 2: every table outside the seeded ones and the delete log byte-identical', diff2.length === 0, diff2.join(', '))
  const again = await flaggedClients(c)
  check('c10', 'seed 2: 13 clients, stages as before', again.length === 13 && Object.entries(STAGES).every(([s, n]) => again.filter(x => x.stage === s).length === n))
  await mustRun(c, genSeed(), 'seed 3 without a wipe')
  check('c11', 'a re-run with no wipe first does not double up', JSON.stringify(await sampleCounts(c)) === JSON.stringify(first))
  await c.close()

  // ── controls: the hazards are real and these tests would see them ─────────
  section('controls: remove a safety on a clone, and the tests must see it')
  const noDisable = await fresh(base)
  const unsafe = DISABLED.reduce((s, n) => s.replace(new RegExp(`alter table public\\.\\w+ (dis|en)able trigger ${n};\\n`, 'g'), ''), seedSql)
  await mustRun(noDisable, unsafe, 'the seed with no disable lines')
  const rMonth = (await one(noDisable, `select leaderboard_rank1_notified_month m from public.profiles where id = '${R}'`)).m
  check('k1', `with the triggers left on, R's rank-1 month gets set (${rMonth}), so d5 is a real test`, rMonth !== null)
  const msgBells = await count(noDisable, `select count(*) from public.notifications where type = 'message' and profile_id in ('${A}', '${F}') and link like '/messages?thread=%'`)
  check('k2', `with the triggers left on, the messages ring the test accounts (${msgBells} bells), so d8 is a real test`, msgBells > 0)
  await mustRun(noDisable, wipeSql, 'the wipe')
  const msgLeft = await count(noDisable, `select count(*) from public.notifications where type = 'message' and profile_id in ('${A}', '${F}')`)
  check('k3', 'the wipe clears those message bells too, by their thread link', msgLeft === 0, `${msgLeft} left`)
  await noDisable.close()

  const noFilter = await fresh(base)
  const unfiltered = wipeSql.replace(new RegExp(`\\s+and\\s+(assigned_rep_id|agent_id|transfer_agent_id)\\s*=\\s*'${A}'`, 'g'), '')
  await mustRun(noFilter, unfiltered, 'the wipe with no agent filter')
  check('k4', "with the agent filter removed, the wipe takes O's rows, so c3 is a real test", await othersSnapshot(noFilter) !== before.others)
  await noFilter.close()

  const missing = await fresh(base)
  const stop = await run(missing, genSeed('00000000-0000-4000-8000-00000000f0ff'))
  check('k5', 'a fulfillment id that does not exist stops the seed with a plain message and changes nothing',
    /does not exist or is not an active fulfillment account/.test(stop?.message ?? '')
    && await count(missing, `select count(*) from public.policies where is_sample and agent_id = '${A}'`) === 0)
  await missing.close()

  const young = await fresh(base)
  await mustRun(young, seedSql.replace("pg_temp.wk_start() - interval '12 days'", "pg_temp.wk_start() - interval '3 days'"), 'the seed with one policy 3 days back')
  const mC = await mondaySummary(young)
  check('k7', `a policy only 3 days before this week would reach the admin's Monday summary ("${mC[0]?.subject}"), so d10 is a real test and 9 days is why it passes`, JSON.stringify(mC) !== JSON.stringify(mA), JSON.stringify(mC))
  await young.close()

  const noView = await fresh(base)
  await noView.exec('drop view public.agent_clients')
  const stop2 = await run(noView, seedSql)
  check('k6', 'with migration 193 missing, the seed stops with a plain message', /migration 193 is not applied/.test(stop2?.message ?? ''), stop2?.message)
  await noView.close()

  // ── the audit ─────────────────────────────────────────────────────────────
  section('audit: qa/servicing-seed/trigger-audit.md against pg_trigger in the replay')
  const live = await rows(base, `select c.relname::text as t, g.tgname::text as n from pg_trigger g join pg_class c on c.oid = g.tgrelid
                                  join pg_namespace s on s.oid = c.relnamespace
                                 where s.nspname = 'public' and not g.tgisinternal and c.relname = any ($1) order by 1, 2`, [SEEDED])
  const crons = await rows(base, 'select jobname from cron.job order by 1')
  const audit = readAudit()
  const key = (on, name) => `${on}.${name}`
  const listed = new Set(audit.map(a => key(a.on, a.name)))
  const shouldList = [...live.map(g => key(g.t, g.n)), ...crons.map(j => key('cron', j.jobname))]
  const notListed = shouldList.filter(k => !listed.has(k))
  check('t1', `all ${live.length} triggers on the ${SEEDED.length} seeded tables and all ${crons.length} cron jobs are listed`, notListed.length === 0, `missing: ${notListed.join(', ')}`)
  const stale = [...listed].filter(k => !shouldList.includes(k))
  check('t2', 'nothing is listed that the replay does not have', stale.length === 0, `stale: ${stale.join(', ')}`)
  const bad = audit.filter(a => a.cells.length !== 3 || a.cells.some(x => !x))
  check('t3', 'every row says what it can send, why it cannot fire, and which assertion proves it', bad.length === 0, bad.map(a => key(a.on, a.name)).join(', '))
  const unknown = audit.flatMap(a => [...(a.cells[2] ?? '').matchAll(/\[([\w-]+)\]/g)].map(m => m[1])).filter(id => !ran.has(id))
  const noRef = audit.filter(a => !/\[[\w-]+\]/.test(a.cells[2] ?? ''))
  check('t4', 'every assertion the audit cites ran in this test', unknown.length === 0 && noRef.length === 0, `unknown: ${[...new Set(unknown)].join(', ')}; no id: ${noRef.map(a => key(a.on, a.name)).join(', ')}`)

  // ── the door file ─────────────────────────────────────────────────────────
  section('door: qa/servicing-seed/door-dry-run.sql')
  const door = readFileSync(DOOR, 'utf8').replaceAll('\r\n', '\n') // git may check it out with CRLF
  const expected = python(['-c', `import sys; sys.path.insert(0, 'scripts'); import seed_agent_sample as s; sys.stdout.reconfigure(newline='\\n'); sys.stdout.write(s.build_door(s.PLACEHOLDER_FULFILLMENT_ID))`])
  check('o1', 'the file is exactly what the generator writes', door === expected, 'regenerate it with --door')
  const parts = door.split(/^-- ===== SECTION \d:.*$/m)
  const titles = [...door.matchAll(/^-- ===== SECTION (\d):/gm)].map(m => m[1]).join('')
  check('o2', 'four sections in order: pre-check, trigger list, wipe and seed, post-check', titles === '1234' && parts.length === 5, titles)
  const [, sec1, sec2, sec3, sec4] = parts
  check('o3', 'section 3 is the seed exactly, test agent only, with the disable and enable lines',
    sec3.includes(seedSql.trimEnd()) && DISABLED.every(n => sec3.includes(` disable trigger ${n};`) && sec3.includes(` enable trigger ${n};`)) && sec3.includes('do $wipe$'))
  const readOnly = /\b(insert\s+into|update\s+public|delete\s+from|alter\s+table|create\s+|drop\s+|truncate|set\s+local)\b/i
  check('o4', 'sections 1, 2 and 4 hold no write', ![sec1, sec2, sec4].some(s => readOnly.test(s.replace(/--[^\n]*/g, ''))))
  const uuids = new Set([...door.matchAll(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g)].map(m => m[0]))
  const outsiders = [...uuids].filter(u => [R, O, REP, Z].includes(u))
  check('o5', 'the file names no agent but the test agent', uuids.has(A) && outsiders.length === 0, outsiders.join(', '))

  const d1 = await fresh(base)
  const asReadOnly = async (d, sql) => {
    await d.exec('begin transaction read only')
    const res = await d.query(sql.replace(/;\s*$/, ''))
    await d.exec('rollback')
    return res.rows
  }
  const pre = await asReadOnly(d1, sec1.replace(/--[^\n]*/g, '').trim())
  const row = (what, flag) => pre.find(r => r.what === what && r.flag === flag)
  check('o6', 'section 1 runs read-only and names flagged and unflagged counts', row('a. all policies', 'flagged')?.policies === 0 && row('a. all policies', 'unflagged')?.policies === 1 && row('a. all policies', 'unflagged')?.clients === 1, JSON.stringify(pre.slice(0, 3)))
  check('o7', 'section 1 lists the unflagged policy by id, and the fulfillment accounts to pick from', pre.some(r => r.id === UNFLAGGED && r.what.startsWith('c.')) && pre.some(r => r.id === F && r.what.startsWith('e.')))
  const preNoFlag = await fresh(base)
  await preNoFlag.exec('drop view public.agent_clients cascade')
  await preNoFlag.exec('alter table public.policies drop column is_sample cascade')
  const preOld = await asReadOnly(preNoFlag, sec1.replace(/--[^\n]*/g, '').trim())
  check('o8', 'section 1 still runs on a database without 186 and 193, and says so', preOld.some(r => /186 is_sample: false, 193 agent_clients: false/.test(r.detail ?? '')), JSON.stringify(preOld.filter(r => r.what.startsWith('d.'))))
  await preNoFlag.close()
  const odd = await fresh(base)
  const ODD = 'dddddddd-dddd-4ddd-8194-000000000004'
  await odd.exec(`insert into public.policies (id, agent_id, client_first_name, client_last_name, status, is_sample)
                  values ('${ODD}', '${A}', 'Looks', 'Real', 'Submitted', true);
                  update public.policies set is_sample = true where id = '${UNFLAGGED}';`)
  const oddF = (await asReadOnly(odd, sec1.replace(/--[^\n]*/g, '').trim())).filter(r => r.what.startsWith('f.')).map(r => r.id)
  check('o15', 'section 1 row f lists a flagged policy with no sample note, and not a flagged P729 row', oddF.length === 1 && oddF[0] === ODD, JSON.stringify(oddF))
  await odd.close()
  const tied = await fresh(base)
  await mustRun(tied, seedSql, 'the seed')
  const preSeeded = await asReadOnly(tied, sec1.replace(/--[^\n]*/g, '').trim())
  check('o17', 'section 1 row g is empty on rows the seed wrote itself', !preSeeded.some(r => r.what.startsWith('g.')), JSON.stringify(preSeeded.filter(r => r.what.startsWith('g.'))))
  const TIED_POLICY = (await one(tied, `select id::text from public.policies where is_sample and agent_id = '${A}' order by id limit 1`)).id
  await tied.exec(`insert into public.fulfillment_cancels (policy_id, rep_id, week_start, amount_cents) values ('${TIED_POLICY}', '${REP}', date_trunc('week', now())::date, 1000);
                   insert into public.leads (business_name, contact_name, phone, lead_type, lead_source, assigned_rep_id, inbound_stage, client_policy_id, is_sample)
                   values ('Unflagged Lead', 'Unflagged Lead', '+15550109996', 'policy_review', 'referral', '${A}', 'new', '${TIED_POLICY}', false);`)
  const tiedRows = (await asReadOnly(tied, sec1.replace(/--[^\n]*/g, '').trim())).filter(r => r.what.startsWith('g.')).map(r => `${r.detail}=${r.policies}`).sort()
  check('o18', `section 1 row g lists a pay row and an unflagged lead tied to a flagged policy (${tiedRows.join(', ')})`, JSON.stringify(tiedRows) === JSON.stringify(['fulfillment_cancels.policy_id=1', 'leads.client_policy_id=1']), JSON.stringify(tiedRows))
  await mustRun(tied, wipeSql, 'the wipe')
  const unlinked = await count(tied, `select count(*) from public.fulfillment_cancels where policy_id is null`)
  check('o19', 'control: the wipe really would unlink that pay row, so the stop rule is needed', unlinked === 1, `${unlinked}`)
  await tied.close()
  const list =await asReadOnly(d1, sec2.replace(/--[^\n]*/g, '').trim())
  check('o9', `section 2 runs read-only: ${list.filter(r => r.kind === 'trigger').length} triggers, ${list.filter(r => r.kind === 'cron').length} cron jobs, none outside the audit`, list.length === live.length + crons.length && list.every(r => r.audit === 'in the audit'))
  const drift = await fresh(base)
  await drift.exec(`create function public.drift_fn() returns trigger language plpgsql as $f$ begin return new; end $f$;
                    create trigger live_only_drift after insert on public.policies for each row execute function public.drift_fn();`)
  const driftList = await asReadOnly(drift, sec2.replace(/--[^\n]*/g, '').trim())
  check('o10', 'a trigger that only live has shows as NOT IN THE AUDIT', driftList.some(r => r.name === 'live_only_drift' && /NOT IN THE AUDIT/.test(r.audit)))
  await drift.close()
  await mustRun(d1, sec3, 'section 3')
  const post = (await asReadOnly(d1, sec4.replace(/--[^\n]*/g, '').trim()))[0]
  check('o11', `with an unflagged row left, section 4 prints a plain failure: "${post.result}"`, /^FAILED: the pages read 3\/7\/2\/1\/1, not 2\/7\/2\/1\/1/.test(post.result) && post.samples_read === '2/7/2/1/1' && Number(post.unflagged_policies) === 1)
  await d1.exec(`delete from public.policies where id = '${UNFLAGGED}'`)
  const post2 = (await asReadOnly(d1, sec4.replace(/--[^\n]*/g, '').trim()))[0]
  check('o12', `with no unflagged row, section 4 reads: "${post2.result}"`, /^PASS: the pages read 2\/7\/2\/1\/1/.test(post2.result))
  await d1.close()
  const d2 = await fresh(base)
  await mustRun(d2, door, 'the whole door file')
  check('o13', 'the whole file also runs top to bottom in one go', await count(d2, `select count(*) from public.policies where is_sample and agent_id = '${A}'`) === 15)
  await d2.close()
  const liveFlip = await fresh(base)
  await mustRun(liveFlip, seedSql, 'the seed')
  check('o16', 'the file holds the stop rules Brayden asked for, before section 1',
    ['FOR EAGLE', 'in the approvals record', 'any unflagged policy', 'row d reads false', 'row f lists anything', 'row g lists anything', 'clearly the test fulfillment login', 'NOT IN THE AUDIT', 'does not start with PASS'].every(s => door.indexOf(s) > -1 && door.indexOf(s) < door.indexOf('-- ===== SECTION 1:')))
  const flags = await one(liveFlip, 'select sms_live from public.recovery_config')
  check('o14', 'the seed leaves sms_live off', flags.sms_live === false)
  await liveFlip.close()

  await base.close()
  console.log(`\nResult: ${failed ? `${failed} FAILED` : 'all passed'}. ${ran.size} checks in ${((Date.now() - t0) / 1000).toFixed(1)} s. Exit code ${failed ? 1 : 0}.`)
  return failed ? 1 : 0
}

let exitCode = 1
try {
  exitCode = await main()
} catch (e) {
  console.error(`CRASH: ${e.stack ?? e}`)
  exitCode = 1
}
process.exit(exitCode)
